    {"t": 56.0, "event": "Клиент забирает документ и уходит из кассового узла."},
    {"t": 58.0, "event": "Клиент выходит за дверь, дверь остаётся открытой."},
    {"t": 64.0, "event": "Второй клиент (мужчина в тёмной одежде) подходит к открытой двери."},
    {"t": 68.0, "event": "Второй клиент садится, на столе кассира лежат деньги (пачка купюр)."},
